text:
Componente client-side con `IntersectionObserver`: cambia al cruzar el borde inferior del hero, sin escuchar continuamente el scroll.

```tsx
"use client";

import Link from "next/link";
import { useEffect, useState } from "react";

const links = [
  { href: "#proyecto", label: "Proyecto" },
  { href: "#servicios", label: "Servicios" },
  { href: "#contacto", label: "Contacto" },
];

type NavbarProps = {
  heroId?: string;
};

export function Navbar({ heroId = "hero" }: NavbarProps) {
  const [hasPassedHero, setHasPassedHero] = useState(false);

  useEffect(() => {
    const hero = document.getElementById(heroId);

    if (!hero) {
      console.warn(`Navbar: no se encontró un elemento con id="${heroId}".`);
      return;
    }

    const observer = new IntersectionObserver(
      ([entry]) => {
        const heroIsAboveViewport =
          !entry.isIntersecting && entry.boundingClientRect.bottom <= 0;

        setHasPassedHero(heroIsAboveViewport);
      },
      {
        // Activa el cambio cuando el hero cruza la altura del navbar.
        rootMargin: "-72px 0px 0px 0px",
        threshold: 0,
      },
    );

    observer.observe(hero);

    return () => observer.disconnect();
  }, [heroId]);

  return (
    <header
      data-passed-hero={hasPassedHero}
      className={[
        "fixed inset-x-0 top-0 z-50 h-18",
        "transition-[background-color,box-shadow,color,backdrop-filter] duration-500",
        hasPassedHero
          ? "bg-stone-50/90 text-stone-950 shadow-[0_10px_40px_rgba(28,25,23,0.09)] backdrop-blur-xl"
          : "bg-transparent text-white shadow-none",
      ].join(" ")}
    >
      <nav
        aria-label="Navegación principal"
        className="mx-auto flex h-full max-w-7xl items-center justify-between px-6 lg:px-10"
      >
        <Link
          href="/"
          aria-label="Ir al inicio"
          className="font-serif text-xl tracking-[-0.04em]"
        >
          Estudio<span className="opacity-50">.</span>
        </Link>

        <ul className="flex items-center gap-6 text-sm lg:gap-9">
          {links.map((link) => (
            <li key={link.href}>
              <Link
                href={link.href}
                className="relative py-2 opacity-75 transition-opacity hover:opacity-100 focus-visible:outline-2 focus-visible:outline-offset-4"
              >
                {link.label}
              </Link>
            </li>
          ))}
        </ul>
      </nav>
    </header>
  );
}
```

El hero debe tener el identificador correspondiente:

```tsx
<section id="hero" className="min-h-screen">
  {/* contenido */}
</section>
```

Si usa otro ID: `<Navbar heroId="inicio" />`.
